function openProduct(key){let f=findProductByKey(key)||(openProductRecord&&openProductKey===key?openProductRecord:null),ru=lang==="ru";if(!f)return;openProductKey=key;openProductRecord=f;$("#modalContent").innerHTML=`<div class="kicker">${t(catKey[f.cat]||"catOther")}</div><div style="font-size:42px;margin-top:8px">${esc(f.emoji||"📦")}</div><div class="modal-title-row"><h2 class="modal-title" id="modalTitle">${esc(ru?(f.ru||f.de):(f.de||f.ru))}</h2>${favoriteButton(f,"modal-favorite")}</div><div class="modal-sub">${esc(ru?(f.de||f.ru):(f.ru||f.de))}</div><div class="modal-cols"><div><h4>${t("description")}</h4><p>${esc(ru?(f.descRu||""):(f.descDe||""))}</p><h4>${t("allergens")}</h4><p>${esc(ru?(f.allRu||""):(f.allDe||""))}</p><h4>${t("storage")}</h4><p>${esc(ru?(f.storeRu||""):(f.storeDe||""))}</p></div><div><h4>${t("energy")} · 100 g</h4><table class="nutri-table"><tr><td>${t("energy")}</td><td>${displayMetric(f.cal,0)} kcal</td></tr><tr><td>${t("protein")}</td><td>${displayMetric(f.p,1)} g</td></tr><tr><td>${t("fat")}</td><td>${displayMetric(f.fat,1)} g</td></tr><tr><td>${t("carbs")}</td><td>${displayMetric(f.carb,1)} g</td></tr></table><h4 style="margin-top:18px">${t("production")}</h4><p>${esc(ru?(f.procRu||""):(f.procDe||""))}</p></div></div><div class="disclaimer">${esc(t("sourceNote"))}</div>`;$("#modal").classList.add("show");$("#closeModal").focus()}
function categoryCards(){let cats=[["dairy","🥛","catDairy"],["meat","🍗","catMeat"],["fish","🐟","catFish"],["grain","🌾","catGrain"],["fruit","🥦","catFruit"],["legumes","🫘","legumes"],["oils","🫒","oils"],["drinks","🥤","drinks"],["snacks","🍫","snacks"],["prepared","🍱","prepared"],["other","🫒","catOther"]];$("#categoryGrid").innerHTML=cats.map(([c,e,k])=>`<button type="button" class="category" data-jump="${c}"><span class="emoji">${e}</span><strong>${t(k)}</strong><span>${data.filter(f=>f.cat===c).length} ${t("products")}</span></button>`).join("")}
