const DIARY_KEY="foodlab-nutrition-diary-v1",DIARY_BACKUP_KEY="foodlab-nutrition-diary-v1-backup-v2",DIARY_SETTINGS_KEY="foodlab-diary-settings-v1";
const drawer=$("#nutritionDrawer"),backdrop=$("#drawerBackdrop");let diaryDay=localDayKey(),weekShift=0,diaryBlocked=false,diaryGoal=null,repeatBusy=false,lastRepeatKey="",lastRepeatAt=0;
function openDrawer(){closeMenu();drawer.classList.add("open");backdrop.classList.add("show");drawer.setAttribute("aria-hidden","false");backdrop.setAttribute("aria-hidden","false");document.body.classList.add("drawer-open");$("#drawerClose").focus();drawDiary()}
function closeDrawer(){drawer.classList.remove("open");backdrop.classList.remove("show");drawer.setAttribute("aria-hidden","true");backdrop.setAttribute("aria-hidden","true");document.body.classList.remove("drawer-open")}
function calcDrawer(){const f=data.find(x=>x.id===$("#drawerFoodSelect").value)||data[0],g=Math.max(0,Math.min(5000,Number(String($("#drawerGrams").value).replace(",","."))||0)),m=g/100;if(!f)return;$("#drawerResult").innerHTML='<span class="energy">'+scaledMetric(f.cal,m,0)+' <small>kcal · '+scaledMetric(f.cal,m*4.184,0)+' kJ</small></span><div class="drawer-macros"><div><strong>'+scaledMetric(f.p,m)+' g</strong><span>'+t("protein")+'</span></div><div><strong>'+scaledMetric(f.fat,m)+' g</strong><span>'+t("fat")+'</span></div><div><strong>'+scaledMetric(f.carb,m)+' g</strong><span>'+t("carbs")+'</span></div></div>'}
function validDiaryDate(v){if(!/^\\d{4}-\\d{2}-\\d{2}$/.test(String(v||"")))return false;const [y,m,d]=v.split("-").map(Number),x=new Date(y,m-1,d);return x.getFullYear()===y&&x.getMonth()===m-1&&x.getDate()===d}
