function legacyDate(x){if(validDiaryDate(x.day))return x.day;const m=String(x.date||"").match(/(\\d{1,2})\\.(\\d{1,2})\\.(\\d{4})/);if(!m)return null;const d=m[3]+"-"+m[2].padStart(2,"0")+"-"+m[1].padStart(2,"0");return validDiaryDate(d)?d:null}
function diaryId(){return window.crypto&&crypto.randomUUID?crypto.randomUUID():"d-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2)}
function diaryMigration(){let raw,p;try{raw=localStorage.getItem(DIARY_KEY);if(raw===null)return;p=JSON.parse(raw)}catch{diaryBlocked=true;return}if(p&&p.version===2&&Array.isArray(p.entries))return;if(!Array.isArray(p)){diaryBlocked=true;return}try{let b=localStorage.getItem(DIARY_BACKUP_KEY);if(b!==null&&b!==raw)throw 0;if(b===null)localStorage.setItem(DIARY_BACKUP_KEY,raw);if(localStorage.getItem(DIARY_BACKUP_KEY)!==raw)throw 0;const entries=p.filter(x=>x&&typeof x==="object").map(x=>({...x,id:x.id||diaryId(),day:legacyDate(x),meal:["breakfast","lunch","dinner","snack"].includes(x.meal)?x.meal:null,source:x.source||null}));localStorage.setItem(DIARY_KEY,JSON.stringify({version:2,entries}));const check=JSON.parse(localStorage.getItem(DIARY_KEY));if(check.version!==2||!Array.isArray(check.entries))throw 0}catch{diaryBlocked=true}}
