function dayOf(x){return validDiaryDate(x.day)?x.day:legacyDate(x)}
function stepDay(day,n){const [y,m,d]=day.split("-").map(Number),x=new Date(y,m-1,d);x.setDate(x.getDate()+n);return localDayKey(x)}
function kcalTotal(rows){const a=rows.filter(x=>Number.isFinite(x.kcal));return a.length?a.reduce((s,x)=>s+x.kcal,0).toFixed(0)+(a.length<rows.length?" · "+t("partial"):""):"—"}
