function sourceFor(f){return {source:"catalog",productId:String(f.id),per100:{kcal:Number.isFinite(f.cal)?f.cal:null,p:Number.isFinite(f.p)?f.p:null,fat:Number.isFinite(f.fat)?f.fat:null,carb:Number.isFinite(f.carb)?f.carb:null}}}
