function entryMarkup(x){return '<div class="diary-item"><div><strong>'+esc(x.name||t("unknownProduct"))+'</strong><small>'+(Number.isFinite(x.grams)?x.grams:"—")+' g</small></div><div class="diary-item-values"><b>'+(Number.isFinite(x.kcal)?x.kcal.toFixed(0):"—")+' kcal</b><small>'+t("protein")+' '+(Number.isFinite(x.p)?x.p.toFixed(1):"—")+' g · '+t("fat")+' '+(Number.isFinite(x.fat)?x.fat.toFixed(1):"—")+' g · '+t("carbs")+' '+(Number.isFinite(x.carb)?x.carb.toFixed(1):"—")+' g</small></div><div class="diary-item-actions"><button type="button" data-edit="'+esc(x.id)+'">'+t("edit")+'</button><button type="button" data-copy-entry="'+esc(x.id)+'">'+t("repeat")+'</button><button type="button" data-delete="'+esc(x.id)+'">'+t("delete")+'</button></div></div>'}
function weekMarkup(entries){const [y,m,d]=diaryDay.split("-").map(Number),monday=new Date(y,m-1,d);monday.setDate(monday.getDate()-((monday.getDay()+6)%7)+weekShift*7);let keys=[];for(let i=0;i<7;i++){const z=new Date(monday);z.setDate(z.getDate()+i);keys.push(localDayKey(z))}const btns=keys.map(k=>{const rows=entries.filter(x=>dayOf(x)===k),known=rows.filter(x=>Number.isFinite(x.kcal)),state=!rows.length?"empty":!known.length?"unknown":known.length<rows.length?"partial":"logged";return '<button class="week-day '+state+(k===diaryDay?" selected":"")+'" type="button" data-week-date="'+k+'"><span>'+new Date(...k.split("-").map(Number).map((v,i)=>i===1?v-1:v)).toLocaleDateString(lang==="ru"?"ru-RU":"de-DE",{weekday:"short"})+'</span><b>'+k.slice(-2)+'</b><small>'+(!rows.length?t("weekNoEntries"):!known.length?t("unknown"):kcalTotal(rows)+" kcal")+'</small></button>'}).join("");return '<div class="week-head"><button id="weekPrev" type="button">‹</button><strong>'+keys[0]+' — '+keys[6]+'</strong><button id="weekNext" type="button">›</button></div><div class="week-grid">'+btns+'</div><small>'+t("weekDaysWithEntries")+": "+keys.filter(k=>entries.some(x=>dayOf(x)===k)).length+"/7</small>"}
function recentRows(entries){const seen=new Set(),out=[];entries.forEach(x=>{const key=x.source?.source==="off"&&x.source.barcode?"off:"+x.source.barcode:x.source?.productId?"catalog:"+x.source.productId:null;if(!key||seen.has(key)||out.length>=10)return;seen.add(key);out.push({...x,_key:key})});return out}
function drawDiary(){const all=readDiary(),dayRows=all.filter(x=>dayOf(x)===diaryDay),dated=all.filter(dayOf);$("#diaryDate").value=diaryDay;$("#entryDay").value=diaryDay;$("#diaryStorageError").hidden=!diaryBlocked;$("#diaryTotals").innerHTML='<strong>'+t("diaryTotal")+' · '+diaryDay+'</strong><span>'+(dayRows.length?dayRows.length+" "+t("portionCount")+" · "+kcalTotal(dayRows)+" kcal · "+t("protein")+" "+macroTotal(dayRows,"p")+" g · "+t("fat")+" "+macroTotal(dayRows,"fat")+" g · "+t("carbs")+" "+macroTotal(dayRows,"carb")+" g":t("dayEmpty"))+"</span>";$("#diaryList").innerHTML=dayRows.length?["breakfast","lunch","dinner","snack","none"].map(k=>{const rows=dayRows.filter(x=>(x.meal||"none")===k);if(k==="none"&&!rows.length)return "";return '<section class="diary-meal"><div class="diary-meal-head"><h4>'+mealText(k)+'</h4><strong>'+(rows.length?kcalTotal(rows)+" kcal":"")+'</strong><button type="button" data-meal-add="'+(k==="none"?"":k)+'">'+t("addProduct")+'</button></div>'+(rows.length?'<small>'+t("protein")+" "+macroTotal(rows,"p")+" g · "+t("fat")+" "+macroTotal(rows,"fat")+" g · "+t("carbs")+" "+macroTotal(rows,"carb")+' g</small><div class="diary-day-items">'+rows.map(entryMarkup).join("")+"</div>":"")+"</section>"}).join("")+'<button type="button" data-day-add class="btn">'+t("emptyAdd")+"</button>":'<div class="diary-empty"><p>'+t("dayEmpty")+'</p><button type="button" data-day-add class="btn">'+t("emptyAdd")+"</button></div>";const undated=all.filter(x=>!dayOf(x));if(undated.length)$("#diaryList").innerHTML+='<section class="diary-meal"><h4>'+t("undated")+'</h4>'+undated.map(entryMarkup).join("")+"</section>";$("#diaryWeek").innerHTML=weekMarkup(dated);const recent=recentRows(all);$("#diaryRecent").innerHTML=recent.length?recent.map(x=>'<button class="recent-product" type="button" data-recent="'+esc(x._key)+'">'+esc(x.name)+' · '+(x.grams||"—")+' g</button>').join(""):"<small>"+t("recentEmpty")+"</small>";if(document.activeElement!==$("#diaryGoal"))$("#diaryGoal").value=diaryGoal||"";const known=dayRows.filter(x=>Number.isFinite(x.kcal));$("#diaryGoalStatus").innerHTML=diaryGoal?'<span>'+t("goalValue")+": "+diaryGoal+" kcal</span>"+(dayRows.length&&known.length===dayRows.length?'<progress max="'+diaryGoal+'" value="'+Math.min(known.reduce((a,x)=>a+x.kcal,0),diaryGoal)+'"></progress>':"<small>"+(dayRows.length?t("goalPartial"):t("goalNoEntries"))+"</small>"):t("goalUnset")}
function errMsg(s){$("#diaryStorageError").hidden=false;$("#diaryStorageError").textContent=s}
function massValue(v){const s=String(v||"").trim().replace(",",".");if(!/^\\d+(?:\\.\\d+)?$/.test(s))return null;const n=Number(s);return n>0&&n<=5000?n:null}
function addDiary(){const g=massValue($("#drawerGrams").value),f=data.find(x=>x.id===$("#drawerFoodSelect").value)||data[0],day=$("#entryDay").value,meal=$("#entryMeal").value,err=$("#diaryAddError");err.textContent="";if(!g){err.textContent=t("massError");$("#drawerGrams").focus();return}if(!validDiaryDate(day)){err.textContent=t("dateError");return}if(!meal){err.textContent=t("mealRequired");$("#entryMeal").focus();return}const m=g/100,x={id:diaryId(),name:lang==="ru"?f.ru:f.de,productId:String(f.id),source:sourceFor(f),grams:g,kcal:Number.isFinite(f.cal)?Math.round(f.cal*m):null,p:Number.isFinite(f.p)?+(f.p*m).toFixed(1):null,fat:Number.isFinite(f.fat)?+(f.fat*m).toFixed(1):null,carb:Number.isFinite(f.carb)?+(f.carb*m).toFixed(1):null,day,meal,date:new Date().toLocaleString(lang==="ru"?"ru-RU":"de-DE")},rows=readDiary();rows.unshift(x);if(!saveDiary(rows)){errMsg(t("saveError"));return}diaryDay=day;drawDiary();$("#addDiary").textContent=t("diarySaved");setTimeout(()=>$("#addDiary").textContent=t("addDiary"),1200)}
function editDiary(id,button){const x=readDiary().find(a=>a.id===id),row=button.closest(".diary-item");if(!x)return;row.innerHTML='<form data-edit="'+esc(id)+'"><label>'+t("grams")+'<input name="grams" inputmode="decimal" value="'+(x.grams||"")+'"></label><label>'+t("date")+'<input name="day" type="date" value="'+(dayOf(x)||"")+'"></label><label>'+t("meal")+'<select name="meal"><option value="">'+t("mealChoose")+'</option>'+["breakfast","lunch","dinner","snack"].map(k=>'<option value="'+k+'" '+(x.meal===k?"selected":"")+'>'+mealText(k)+'</option>').join("")+'</select></label><small class="edit-error"></small>'+(x.source?.per100?"":"<small>"+t("editNoBase")+"</small>")+'<button class="btn" type="submit">'+t("save")+'</button><button type="button" data-cancel>'+t("cancel")+"</button></form>";row.querySelector("[name=grams]").focus()}
function commitEdit(form){const rows=readDiary(),i=rows.findIndex(x=>x.id===form.dataset.edit);if(i<0)return;const x=rows[i],g=massValue(form.elements.grams.value),d=form.elements.day.value,m=form.elements.meal.value,e=form.querySelector(".edit-error");if(!g){e.textContent=t("massError");return}if(!validDiaryDate(d)){e.textContent=t("dateError");return}const patch={...x,day:d,meal:m||null};if(g!==x.grams){const calc=recalcEntry(x,g);if(!calc){e.textContent=t("editNoBase");return}Object.assign(patch,calc)}rows[i]=patch;if(!saveDiary(rows)){e.textContent=t("saveError");return}diaryDay=d;drawDiary()}
function repeatMeal(sd,sm,td,tm){const guard=[sd,sm,td,tm].join("|"),now=Date.now();if(repeatBusy||(guard===lastRepeatKey&&now-lastRepeatAt<900))return;const all=readDiary(),src=all.filter(x=>dayOf(x)===sd&&x.meal===sm);if(!src.length){$("#repeatMessage").textContent=t("repeatNoEntries");return}if(!confirm(t("repeatConfirm")+" ("+src.length+" "+t("portionCount")+")?"))return;lastRepeatKey=guard;lastRepeatAt=now;repeatBusy=true;$("#repeatConfirm").disabled=true;const copies=src.map(x=>({...x,id:diaryId(),day:td,meal:tm,date:new Date().toLocaleString()})),ok=saveDiary(copies.concat(all));repeatBusy=false;$("#repeatConfirm").disabled=false;if(!ok){$("#repeatMessage").textContent=t("saveError");return}diaryDay=td;$("#repeatMessage").textContent=t("repeatDone");drawDiary()}
function showRepeatPreview(){const a=readDiary().filter(x=>dayOf(x)===$("#repeatSourceDay").value&&x.meal===$("#repeatSourceMeal").value);$("#repeatPreview").innerHTML=a.length?a.map(x=>"<div>"+esc(x.name)+" · "+x.grams+" g</div>").join(""):"<small>"+t("repeatNoEntries")+"</small>"}
function localizeDiarySelects(){const meals=["breakfast","lunch","dinner","snack"],keys=["mealBreakfast","mealLunch","mealDinner","mealSnack"];for(const id of ["entryMeal","repeatTargetMeal"]){const el=$("#"+id),old=el.value;el.innerHTML='<option value="">'+t("mealChoose")+'</option>'+meals.map((k,i)=>'<option value="'+k+'">'+t(keys[i])+'</option>').join("");el.value=old}const src=$("#repeatSourceMeal"),v=src.value;src.innerHTML=meals.map((k,i)=>'<option value="'+k+'">'+t(keys[i])+'</option>').join("");src.value=v||"breakfast"}
function initDiary(){diaryMigration();try{const x=JSON.parse(localStorage.getItem(DIARY_SETTINGS_KEY)||"{}");diaryGoal=Number.isFinite(x.goal)&&x.goal>0?x.goal:null}catch{diaryGoal=null}$("#diaryDate").value=diaryDay;$("#entryDay").value=diaryDay;$("#repeatSourceDay").value=diaryDay;$("#repeatTargetDay").value=diaryDay;showRepeatPreview()}
$("#drawerFoodSelect").addEventListener("change",calcDrawer);$("#drawerGrams").addEventListener("input",calcDrawer);
$("#diaryDate").addEventListener("change",()=>{if(validDiaryDate($("#diaryDate").value)){diaryDay=$("#diaryDate").value;weekShift=0;drawDiary()}});
$("#diaryPrev").addEventListener("click",()=>{diaryDay=stepDay(diaryDay,-1);weekShift=0;drawDiary()});$("#diaryNext").addEventListener("click",()=>{diaryDay=stepDay(diaryDay,1);weekShift=0;drawDiary()});$("#diaryToday").addEventListener("click",()=>{diaryDay=localDayKey();weekShift=0;drawDiary()});
$("#entryDay").addEventListener("change",()=>{if(validDiaryDate($("#entryDay").value))diaryDay=$("#entryDay").value;drawDiary()});
$("#addDiary").addEventListener("click",addDiary);
$("#clearDiary").addEventListener("click",()=>{if(readDiary().length&&confirm(t("diaryConfirm"))){if(saveDiary([]))drawDiary();else errMsg(t("saveError"))}});
$("#diaryGoalSave").addEventListener("click",()=>{const v=$("#diaryGoal").value.trim(),n=v?Number(v):null;if(v&&(!Number.isFinite(n)||n<=0||n>100000)){errMsg(t("goalError"));return}try{diaryGoal=n;localStorage.setItem(DIARY_SETTINGS_KEY,JSON.stringify({goal:n}));drawDiary()}catch{errMsg(t("saveError"))}});
$("#diaryGoalClear").addEventListener("click",()=>{try{diaryGoal=null;localStorage.setItem(DIARY_SETTINGS_KEY,JSON.stringify({goal:null}));drawDiary()}catch{errMsg(t("saveError"))}});
$("#diaryWeek").addEventListener("click",e=>{if(e.target.closest("#weekPrev"))weekShift--;else if(e.target.closest("#weekNext"))weekShift++;else{const b=e.target.closest("[data-week-date]");if(b){diaryDay=b.dataset.weekDate;weekShift=0}}drawDiary()});
$("#diaryList").addEventListener("click",e=>{const a=e.target.closest("[data-edit]");if(a){editDiary(a.dataset.edit,a);return}const d=e.target.closest("[data-delete]");if(d&&confirm(t("deleteConfirm"))){const rows=readDiary().filter(x=>x.id!==d.dataset.delete);if(saveDiary(rows))drawDiary();else errMsg(t("saveError"));return}const r=e.target.closest("[data-copy-entry]");if(r){const x=readDiary().find(y=>y.id===r.dataset.copyEntry);if(x?.meal){$("#repeatSourceDay").value=dayOf(x);$("#repeatSourceMeal").value=x.meal;$("#repeatTargetDay").value=diaryDay;$("#repeatTargetMeal").value=x.meal;showRepeatPreview()}return}const m=e.target.closest("[data-meal-add]");if(m){$("#entryDay").value=diaryDay;$("#entryMeal").value=m.dataset.meal;$("#drawerFoodSelect").focus();return}if(e.target.closest("[data-day-add]")){$("#entryDay").value=diaryDay;$("#entryMeal").value="";$("#drawerFoodSelect").focus();return}if(e.target.closest("[data-cancel]"))drawDiary()});
$("#diaryList").addEventListener("submit",e=>{const f=e.target.closest("form[data-edit]");if(f){e.preventDefault();commitEdit(f)}});
$("#repeatSourceDay").addEventListener("change",showRepeatPreview);$("#repeatSourceMeal").addEventListener("change",showRepeatPreview);$("#repeatConfirm").addEventListener("click",()=>{const sd=$("#repeatSourceDay").value,sm=$("#repeatSourceMeal").value,td=$("#repeatTargetDay").value,tm=$("#repeatTargetMeal").value;if(validDiaryDate(sd)&&validDiaryDate(td)&&sm&&tm)repeatMeal(sd,sm,td,tm);else $("#repeatMessage").textContent=t("repeatFields")});
$("#repeatQuick").addEventListener("click",()=>repeatMeal(stepDay(diaryDay,-1),"breakfast",diaryDay,"breakfast"));
$("#diaryRecent").addEventListener("click",e=>{const b=e.target.closest("[data-recent]");if(!b)return;const x=recentRows(readDiary()).find(a=>a._key===b.dataset.recent),f=x?.source?.productId&&data.find(y=>String(y.id)===String(x.source.productId));if(!f){errMsg(t("recentReselect"));$("#drawerFoodSelect").focus();return}$("#drawerFoodSelect").value=f.id;$("#drawerGrams").value=x.grams||150;$("#entryDay").value=diaryDay;$("#entryMeal").focus();calcDrawer()});
initDiary();drawDiary();
$("#search").value=typeof savedFilters.productQuery==="string"?savedFilters.productQuery:"";document.querySelectorAll(".chip").forEach(b=>b.classList.toggle("active",b.dataset.cat===activeCat));setLang(lang);
(function(){
 const TEAS=window.FOODLAB_TEAS||[];
 const page=document.getElementById('teaPage');
 if(!page) return;
 const $id=id=>document.getElementById(id);
 const ru=()=>document.documentElement.lang!=='de';
 const tr=(r,d)=>ru()?r:d;
 const category=$id('teaCategory'),search=$id('teaSearch'),grid=$id('teaGrid');
 function normalizeTeaSearch(value){return String(value||"").normalize("NFD").replace(/[\\u0300-\\u036f]/g,"").toLocaleLowerCase()}
 const cats=[...new Set(TEAS.map(x=>x[0]))];
 const teaIndex=TEAS.map(x=>normalizeTeaSearch(x.join(" ")));
 let searchTimer;
 function saveTeaFilters(){saveFilters({teaQuery:search.value,teaCategory:category.value==="all"?"all":cats[Number(category.value)]||"all"})}
 function initCategories(){
  const labels=cats.map(cat=>{const row=TEAS.find(x=>x[0]===cat);return ru()?cat:row?.[1]||cat});
  category.innerHTML='<option value="all">'+tr('Все виды','Alle Sorten')+'</option>'+labels.map((c,i)=>'<option value="'+i+'">'+c+'</option>').join('');
  category.dataset.cats=JSON.stringify(cats);
  search.value=typeof savedFilters.teaQuery==="string"?savedFilters.teaQuery:"";
  search.placeholder=tr('Найти чай, вкус или аромат…','Tee, Geschmack oder Aroma suchen…');
  search.setAttribute('aria-label',tr('Поиск чая','Teesuche'));
  const savedCategory=cats.indexOf(savedFilters.teaCategory);
  category.value=savedCategory<0?"all":String(savedCategory);
 }
 function render(){
  const q=normalizeTeaSearch(search.value);
  const selected=category.value==='all'?'all':cats[Number(category.value)];
  const list=TEAS.filter((x,i)=>(selected==='all'||x[0]===selected)&&(!q||teaIndex[i].includes(q)));
  grid.innerHTML=list.map((x,i)=>`<article class="tea-card"><div class="tea-card-top"><div><div class="tea-group">${ru()?x[0]:x[1]}</div><h3>${ru()?x[2]:x[3]}</h3><div class="tea-de">${ru()?x[3]:x[2]}</div></div><span aria-hidden="true">🍵</span></div><p>${x[4]}</p><div class="tea-rec"><b>${tr('Рекомендация:','Empfehlung:')}</b> ${x[5]}</div></article>`).join('');
  $id('teaCount').textContent=tr(list.length+' из '+TEAS.length+' чаёв',list.length+' von '+TEAS.length+' Tees');
  $id('teaEmpty').hidden=!!list.length;
 }
function showTea(){
  document.querySelector('main').hidden=true;
  document.querySelector('footer.footer').hidden=true;
  page.hidden=false;window.scrollTo({top:0,behavior:'instant'});
  initCategories();render();
 }
 function hideTea(){
  page.hidden=true;document.querySelector('main').hidden=false;
  document.querySelector('footer.footer').hidden=false;window.scrollTo({top:0,behavior:'smooth'});
 }
 document.addEventListener('foodlab:tea-open',()=>{initCategories();render();});
 search.addEventListener('input',()=>{saveFilters({teaQuery:search.value});clearTimeout(searchTimer);searchTimer=setTimeout(render,90)});category.addEventListener('change',()=>{saveTeaFilters();render()});
 const oldSetLang=window.setLang;
 // The site's language switch updates documentElement.lang; refresh the tea interface on return/open.
 const langButton=document.getElementById('langBtn');
 langButton?.addEventListener('click',()=>{if(!page.hidden)setTimeout(()=>{initCategories();render();},0);});
})();





/* Unified interaction controller: one click path for navigation, drawers and overlays. */
(function () {
  'use strict';
  const $ = (id) => document.getElementById(id);
  const menu = $('sideMenu');
  const menuBackdrop = $('menuBackdrop');
  const menuToggle = $('menuToggle');
  const nutrition = $('nutritionDrawer');
  const nutritionBackdrop = $('drawerBackdrop');
  const productModal = $('modal');
  const teaPage = $('teaPage');
  const main = document.querySelector('main');
  const footer = document.querySelector('footer.footer');

  if (!menu || !menuBackdrop || !menuToggle) return;

  const setOpen = (panel, backdrop, isOpen, bodyClass, trigger) => {
    if (!panel || !backdrop) return;
    panel.classList.toggle('open', isOpen);
    backdrop.classList.toggle('show', isOpen);
    panel.setAttribute('aria-hidden', String(!isOpen));
    backdrop.setAttribute('aria-hidden', String(!isOpen));
    document.body.classList.toggle(bodyClass, isOpen);
    if (trigger) trigger.setAttribute('aria-expanded', String(isOpen));
  };

  function closeMenu() { setOpen(menu, menuBackdrop, false, 'menu-open', menuToggle); }
  function openMenu() {
    closeDrawer();
    setOpen(menu, menuBackdrop, true, 'menu-open', menuToggle);
    $('menuClose')?.focus();
  }
  function closeDrawer() { setOpen(nutrition, nutritionBackdrop, false, 'drawer-open'); }
  function openDrawer() {
    closeMenu();
    setOpen(nutrition, nutritionBackdrop, true, 'drawer-open');
    $('drawerClose')?.focus();
    document.dispatchEvent(new CustomEvent('foodlab:drawer-open'));
  }
  function openTea() {
    closeMenu(); closeDrawer();
    if (!teaPage) return;
    if (main) main.hidden = true;
    if (footer) footer.hidden = true;
    teaPage.hidden = false;
    window.scrollTo({ top: 0, behavior: 'instant' });
    // Rebuild localized category labels after any RU/DE switch.
    document.dispatchEvent(new CustomEvent('foodlab:tea-open'));
  }
  function closeTea() {
    if (!teaPage) return;
    teaPage.hidden = true;
    if (main) main.hidden = false;
    if (footer) footer.hidden = false;
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
  function closeOverlays() {
    closeMenu(); closeDrawer();
    productModal?.classList.remove('show');
    if (teaPage && !teaPage.hidden) closeTea();
  }

  menuToggle.addEventListener('click', (event) => {
    event.preventDefault();
    if (menu.classList.contains('open')) closeMenu();
    else openMenu();
  });

  // Delegation makes taps on nested icons, labels and text behave identically.
  document.addEventListener('click', (event) => {
    const target = event.target instanceof Element ? event.target : null;
    if (!target) return;
    if (target.closest('#menuClose') || target === menuBackdrop) {
      event.preventDefault(); closeMenu(); return;
    }
    if (target.closest('#openNutrition, [data-open-nutrition]')) {
      event.preventDefault(); openDrawer(); return;
    }
    if (target.closest('#drawerClose') || target === nutritionBackdrop) {
      event.preventDefault(); closeDrawer(); return;
    }
    if (target.closest('#openTea, [data-open-tea]')) {
      event.preventDefault(); openTea(); return;
    }
    if (target.closest('#teaBack')) {
      event.preventDefault(); closeTea(); return;
    }
    if (target.closest('#sideMenu a[data-menu-close]')) closeMenu();
    if (target.closest('#closeModal')) productModal?.classList.remove('show');
  });

  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') closeOverlays();
  });

  // Ensure controls remain operable if a pointer tap lands on an icon inside them.
  document.querySelectorAll('button, a, [role="button"]').forEach((el) => {
    if (!el.hasAttribute('tabindex') && el.getAttribute('role') === 'button') el.tabIndex = 0;
  });
})();
